import{_ as e,o as a,c as t,ag as _}from"./chunks/framework.Ddwm6YJC.js";const m=JSON.parse('{"title":"第76章 成人礼","description":"","frontmatter":{},"headers":[],"relativePath":"第76章_成人礼.md","filePath":"第76章_成人礼.md"}'),r={name:"第76章_成人礼.md"};function o(n,p,s,c,i,d){return a(),t("div",null,[...p[0]||(p[0]=[_('<h1 id="第76章-成人礼" tabindex="-1">第76章 成人礼 <a class="header-anchor" href="#第76章-成人礼" aria-label="Permalink to &quot;第76章 成人礼&quot;">​</a></h1><p>高三那年秋，风还带着凉意，学校把成人礼放在大操场上。</p><p>通知贴在教室后面，老周站在讲台上念了一遍，念到全体起立宣誓那句，底下有人笑，有人轻轻吸气。</p><p>我坐在靠窗的位置，手指压着桌角，满脑子只有一个念头，人那么多，我能不能一眼找到江苒。</p><p>她在隔壁班，平时课间总能碰上，可到了全年级集合的时候，反而最容易走散。</p><p>前一晚，顾远把校服搭在椅背上，回头问我，紧张吗。我说，有点。他笑，说，几百号人陪着你念，怕什么。</p><p>陈默在后面收书包，头也不抬地说，人越多越好，念错也没人听得见。</p><p>林小满抱着誓词纸一张一张发，纸很薄，字很密。她走到我旁边，压低声音说，你们在西边，她们班在东边，中间隔着主席台。</p><p>我把纸折好塞进口袋，纸角蹭过掌心，有点痒。</p><p>何晓凑过来，问，你们男生背了吗。我说，背了。她不信，让我背第一句，我磕磕绊绊背出来，她笑，说算你过关。</p><p>夜里风从窗缝钻进来，带着潮气。我把誓词纸摊在被子上看了几遍，灯光发黄，字在眼前轻轻晃。</p><p>我担心的是长大这两个字被摆到台面上，让人没法躲。</p><p>江苒发来消息，说，明天风大，多穿点。我回，好，你也是。她问，你紧张吗。我盯着那几个字看了很久，回，有点。她说，我也是。</p><p>过了一会儿，她又发，明天宣誓时，你好好念，别找我。我回，我尽量。</p><p>我把手机扣在枕边，闭上眼，全是风声。</p><p>第二天早晨，天蓝得过分，云走得很快。操场上摆满椅子，白色椅背在阳光下晃眼。</p><p>广播里的音乐有点闷，像隔着一层雾。南雾县春天的雾散得慢，到了上午还留着尾巴，树影都带着水汽。</p><p>我们班集合，女生在前，男生在后。老周穿着深色外套，站在队边点名，点到我时抬头看了一眼，说，站直点，今天精神点。</p><p>我把外套拉链拉到顶，点头。</p><p>顾远站在我左边，不停搓手，说这风真够劲。陈默站在右边，闭着眼背词，嘴唇动得很快。</p><p>主任上台讲话，话筒带着回音，一句话要在操场上荡两圈才落下来。</p><p>我踮脚往东边看，全是人头，校服一个颜色，根本分不清谁是谁。</p><p>太阳升高，照在后颈上，暖烘烘的，风一吹又凉下来，鼻子被激得发酸。</p><p>空气里有塑胶跑道的味道，混着青草香，还有前面同学发梢的淡香。</p><p>林小满回头，冲我做了个加油的口型。我点点头。</p><p>何晓举着班牌，风把牌吹得直晃，她抓得很用力，指节发白。</p><p>主持人说，请全体起立。</p><p>椅子挪动声连成一片，像潮水涌上来。几百人同时起身，脚下都跟着震了一下。</p><p>请举起右拳，放在耳侧。</p><p>我举起手，风从指缝穿过，凉得我抖了一下。</p><p>周围人的誓词纸被吹得哗哗响，像许多小鸟在扑翅膀。</p><p>领誓的声音从主席台传来，洪亮，带着一点颤。</p><p>我们跟着念，第一句出口，声音散在风里，只觉得胸口发烫。</p><p>我念着念着，眼睛忍不住往东边瞟。</p><p>黑压压一片，后脑勺挨着后脑勺，举起的手像一片小树林，我看不见她。</p><p>心里一下就空了，几百人念着同样的话，我却觉得安静，安静到能听见自己的呼吸。</p><p>顾远念得很大声，气息不稳。陈默念得很稳，一个字一个字咬得很重。</p><p>我想起她昨晚的话，好好念，别找我，可我做不到。</p><p>风把东边方阵吹得有点散，有个女生的马尾扬起来，很像她，我盯了两秒，看清发绳颜色不对，心往下一沉。</p><p>又有个侧脸很像她，低头看词，睫毛在阳光下很亮，我刚想细看，她转过头去，是陌生面孔。</p><p>手臂举得发酸，汗从额头滑进眼睛，涩涩的。</p><p>誓词念到一半，风忽然变大，横幅被吹得鼓起，话筒发出一声尖啸，全场都皱眉。</p><p>队伍晃了一下，有人低笑，老周抬手压了压，示意安静。</p><p>我趁机往后排看，她个子不高，应该在中间偏后的位置。</p><p>阳光落在那片区域，白花花的，我眯起眼，只看见一排举起的手，一张张微仰的脸。</p><p>还是没有她。</p><p>口袋里有东西硌了我一下，是早上灌好的保温杯。是周末回家时奶奶灌的，她说暖的，喝了不怕冷。</p><p>杯子旁边是那枚书签，淡蓝色，画着浅浅海浪，是江苒送的。她说，夹在笔袋里，看着就不慌。今天我把它夹在了誓词纸中间。</p><p>杯壁被手焐得发热，暖意透出来，带着一点姜香。</p><p>我忽然很想见她，在所有人都说自己长大的时刻，亲眼看她站在风里，举着拳头。</p><p>誓词接近尾声，领誓的声音拔高，全场的声音跟着拔高，像浪涌到最高处。</p><p>就在那一刻，我看见了。东边靠后的位置，有个女生轻轻踮脚，发尾从衣领滑出来，被风吹到一边。</p><p>那个小动作我太熟悉了，她站久了就会换脚，头发就会滑出来。</p><p>我盯着那个方向，心跳加快，阳光晃眼，看不清脸，只能看见瘦瘦的轮廓，站得很直，拳举得很高。</p><p>我的声音一下哑了，最后一个字念得轻得像叹气。</p><p>主持人说，礼成，请坐。</p><p>坐下去的声音像潮水落下，椅面冰凉，透过裤子渗上来。</p><p>掌声很响，惊起树上几只鸟。我没鼓掌，手还攥着那杯热水，杯壁已经不烫了。</p><p>顾远拍我肩膀，说，解放了。我没说话，眼睛还看着东边。</p><p>陈默递来一瓶水，说，喝点。我喝了一口，凉意滑下去，胸口那团热才散了些。</p><p>老师代表上台讲话，我一个字也没听进去，满脑子都是发尾滑出来的瞬间。</p><p>我想挤过去问她，刚才紧张吗，有没有听见我的声音，可方阵之间隔着过道，站着老师，人群密不透风。</p><p>林小满回头悄声问，你刚才走神了吧。我说，嗯。她笑，说我也是，我一直在找人，愣是没找着。</p><p>何晓小声说，我看见江苒了，最后一排靠过道那个就是。我一下坐直，问，哪边。她说，别急，等散场。</p><p>散场音乐响起，队伍开始松动，有人活动腿脚，有人拿出手机拍照。</p><p>阳光正好，照在每张脸上，都是亮的。空气里有汗味，有头发被晒过的味道，还有远处飘来的甜香。</p><p>老周拍手，说，别乱，拍完合影再走。</p><p>合影时摄影师让我们喊茄子，喊完，人群散开，开始自由活动。</p><p>我绕过主席台往东边跑，风灌进领口，凉得我一哆嗦。顾远在后面喊，你去哪。我头也不回，说，找人。</p><p>人流迎面而来，我逆着走，肩膀被撞了几下，誓词纸掉在地上。</p><p>我弯腰去捡，书签滑出来，落在跑道上，淡蓝海浪朝上。</p><p>一只手先我一步捡起来，手指细，指甲短，袖口别着一枚小小云朵徽章。</p><p>我抬头，逆光里，她站在风里，头发有点乱，手里举着书签，另一只手捧着同样的保温杯。</p><p>她笑着看我，眼睛亮得像被水洗过。</p><p>她说，宣誓的时候，你是不是一直在找我。</p><p>我张嘴，却没说出话，喧闹一下远了，只剩风声，还有杯盖在他掌心碰出的轻响。</p><p>她把书签递过来，指尖碰到我掌心，凉凉的。</p><p>身后有人在喊集合，广播换了首歌，前奏刚起。</p><p>她凑近一步，压低声音说，我有句话没敢大声念，现在只想说给你听。</p><p>我捏紧那杯半温的水，听见心跳一下一下变响。</p><p>而她身后，最后一排靠过道的位置不知何时空了出来，椅子上落着一张没被风吹走的誓词纸，纸角压着一包没拆封的姜汤。</p>',81)])])}const f=e(r,[["render",o]]);export{m as __pageData,f as default};
